import { Pill, PillType, pillRoomNotifLen, pillRoomNotifPos } from \"../../../../src/components/views/elements/Pill\";
import { stubClient } from \"../../../test-utils\";
import dis from \"../../../../src/dispatcher/dispatcher\";
import { Action } from \"../../../../src/dispatcher/actions\";

describe(\"Pill\", () => {
    beforeEach(() => stubClient());

    it(\"exports the room notification helpers\", () => {
        expect(pillRoomNotifPos(\"hello @room again\")).toBe(6);
        expect(pillRoomNotifPos(\"hello\")).toBe(-1);
        expect(pillRoomNotifLen()).toBe(5);
    });

    it(\"renders nothing for an unknown permalink or a user type without an identifier\", () => {
        expect(render(<Pill url=\"https://example.org\" />).container.querySelector(\"bdi\")).toBeNull();
        expect(render(<Pill type={PillType.UserMention} />).container.querySelector(\"bdi\")).toBeNull();
    });

    it(\"keeps the original URL on a message user pill and opens its member\", () => {
        const url = \"https://matrix.to/#/@alice:example.org\";
        const dispatch = jest.spyOn(dis, \"dispatch\").mockImplementation();
        const { container } = render(<Pill url={url} inMessage={true} />);
        const anchor = container.querySelector(\"bdi > a.mx_Pill.mx_UserPill\")"'!;
        expect(anchor.getAttribute("href")).toBe(url);
        expect(anchor.querySelector(".mx_Pill_linkText")?.textContent).toBe("@alice:example.org");
        fireEvent.click(anchor);
        expect(dispatch).toHaveBeenCalledWith(
            expect.objectContaining({ action: Action.ViewUser, member: expect.objectContaining({ userId: "@alice:example.org" }) }),
        );
        dispatch.mockRestore();
    });

    it("uses a span outside messages and falls back to the room alias", () => {
        const { container } = render(<Pill url="https://matrix.to/#/#alias:example.org" />);
        expect(container.querySelector("bdi > a")).toBeNull();
        expect(container.querySelector("bdi > span.mx_Pill.mx_RoomPill .mx_Pill_linkText")?.textContent).toBe(
            "#alias:example.org",
        );
    });
});
