    const localMember = resolvedType === PillType.UserMention && resourceId ? room?.getMember(resourceId) : null;

    useEffect(() => {
        setProfile(null);
        if (resolvedType !== PillType.UserMention || !resourceId || localMember) return;
        let active = true;
        MatrixClientPeg.get()
            .getProfileInfo(resourceId)
            .then((result) => {
                if (active) setProfile({ userId: resourceId, ...result });
            })
            .catch((err) => logger.error("Could not retrieve profile data for " + resourceId + ":", err));
        return () => {
            active = false;
        };
    }, [resolvedType, resourceId, localMember]);

    if (resolvedType === PillType.AtRoomMention) {
        if (!room) return { avatar: null, text: null, onClick: null, resourceId: null, type: null };
        return {
            avatar: <RoomAvatar room={room} width={16} height={16} aria-hidden="true" />,
            text: "@room",
            onClick: null,
            resourceId: room.roomId,
            type: PillType.AtRoomMention,
        };
    }

    if (!resourceId) return { avatar: null, text: null, onClick: null, resourceId: null, type: null };

    if (resolvedType === PillType.UserMention && sigil === "@") {
        const member = localMember || new RoomMember(null, resourceId);
        if (!localMember && profile?.userId === resourceId) {
            member.name = profile.displayname;
            member.rawDisplayName = profile.displayname;
            member.events.member = {
                getContent: () => ({ avatar_url: profile.avatar_url }),
                getDirectionalContent: () => ({ avatar_url: profile.avatar_url }),
            } as MatrixEvent;
        }
        const onClick = (e: ButtonEvent): void => {
            e.preventDefault();
            dis.dispatch({ action: Action.ViewUser, member });
        };
        return {
            avatar: <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />,
            text: member.rawDisplayName || resourceId,
            onClick,
            resourceId,
            type: PillType.UserMention,
        };
    }

    if (resolvedType === PillType.RoomMention && (sigil === "!" || sigil === "#")) {
        const client = MatrixClientPeg.get();
        const resolvedRoom =
            sigil === "#"
                ? client
                      .getRooms()
                      .find(
                          (candidate) =>
                              candidate.getCanonicalAlias() === resourceId ||
                              candidate.getAltAliases().includes(resourceId),
                      )
                : client.getRoom(resourceId);
        return {
            avatar: resolvedRoom ? <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" /> : null,
            text: resolvedRoom?.name || resourceId,
            onClick: null,
            resourceId,
            type: resolvedRoom?.isSpaceRoom() ? "space" : PillType.RoomMention,
        };
    }

    return { avatar: null, text: null, onClick: null, resourceId: null, type: null };
}
